        {
          "stage": "identity",
          "focus": "商品身份",
          "sentences": [
            {
              "display_text": "这只就是日常陶瓷马克杯，陶瓷材质，带把手，米白色。",
              "spoken_text": "这只就是日常陶瓷马克杯，陶瓷材质，带把手，米白色。",
